import { useEffect, useState } from "react";
import Header from "./components/Header"; // ✅ KHÔNG có {}
import ProductCard from "./components/ProductCard"; // ✅ KHÔNG có {}

function App() {
  const [products, setProducts] = useState([]);
  const [cart, setCart] = useState([]);

  useEffect(() => {
    fetch("http://localhost:5000/api/products")
      .then(res => res.json())
      .then(data => setProducts(data))
      .catch(err => console.log(err));
  }, []);

  const addToCart = (p) => {
    setCart([...cart, p]);
  };

  return (
    <div>
      <Header />

      <div style={{ padding: 20 }}>
        <h2>📱 Danh sách iPhone</h2>

        <div style={{ display: "flex", flexWrap: "wrap" }}>
          {products.map(p => (
            <ProductCard 
              key={p._id} 
              p={p} 
              addToCart={addToCart}
            />
          ))}
        </div>

        <h2>🛒 Giỏ hàng ({cart.length})</h2>

        {cart.map((item, index) => (
          <div key={index}>
            {item.name} - {item.price.toLocaleString()} VND
          </div>
        ))}
      </div>
    </div>
  );
}

export default App;
